      box(U(0),.55,V(-hv+1.3),7.0,1.1,1.1,'#2a2f3a');box(U(0),1.15,V(-hv+1.3),7.2,.12,1.3,'#e9e6df');box(U(0),1.55,V(-hv+1.0),6.4,.7,.1,'#c9a24a');solid(U(0),V(-hv+1.3),7.0,1.1,1.2);
