  P(fx + 1, fy + 3, brow); P(fx + 2, fy + 3, brow); P(fx + 5, fy + 3, brow); P(fx + 6, fy + 3, brow);
  P(fx + 1, fy + 4, '#ffffff'); P(fx + 2, fy + 4, d.eye); P(fx + 5, fy + 4, d.eye); P(fx + 6, fy + 4, '#ffffff');
