  if (f.blocking && D.bloqueo) return f.blockHitT > 0 && D.bloqueo_golpe ? { name: 'bloqueo_golpe', time: clamp(.3 - f.blockHitT, 0, .3) } : { name: 'bloqueo', time: .35 };
