    if (f.awak > 0 && D.idle_despierto) return { name: 'idle_despierto', time: G.time % 1.8 };
    if (D.idle_combate && enemiesOf(f).some(g => dist2d(f, g) < 9)) return { name: 'idle_combate', time: G.time % D.idle_combate.length };
