    root.add(g);
    const x = (rnd() - .5) * 280, dd = 62 + rnd() * 92; L.jelly.push({ g, bell, mats: [bell.material, core.material, tm], x, z: SHORE(x) + dd, y: -3.5 - rnd() * 8, ph: rnd() * 6.28, sp: .15 + rnd() * .2, s: .8 + rnd() * 1.4 });
