      if (Math.random() < dt * 4 && near(x, z, 60)) emit(x + rand(-2, 2), sq.g.position.y + rand(-1, 1), z + rand(-2, 2), 0, .5, 0, '#ffcad8', .12, 1.5, 0, 1);
