  SH.camZ += ((SH.faceZoom ? 3.1 : 5.5) - SH.camZ) * Math.min(1, dt * 3.5);
  const ox = SH.faceZoom ? (innerWidth > 820 ? .7 : 0) : (innerWidth > 820 ? 1.0 : 0);
  SH.cam.position.set(ox + Math.sin(SH.t * .3) * .15, SH.faceZoom ? 1.78 : 1.4, SH.camZ);
