  cam.yaw = 0;   // el atacante apunta con la cámara: si venías de una partida, el lanzamiento de la cadena salía hacia otro lado
  vReset(a, 0, 0, 0); vReset(v, 0, D.pull ? 9 : 2.6, Math.PI);
