      NET.lastAct[pe.peer] = pr.act ? pr.act.s : 0;
      px.actSeen = new Set((Array.isArray(pr.acts) ? pr.acts : []).concat(pr.act ? [pr.act] : []).map(a => (a.ss || '') + ':' + a.s));   // lo que ya venia en curso al entrar no se repite
