  o.dmg = clamp(+r.dmg || 1, 1, 999); o.spd = clamp(+r.spd || 1, 1, 3); o.grav = clamp(+r.grav || 1, .1, 1.5); o.dest = clamp(r.dest == null ? 1 : +r.dest, 0, 3); o.rag = clamp(+r.rag || 1, .5, 4);
