  const n = dummies().length, F = fwd(cam.yaw), R = rightOf(cam.yaw), off = (n % 4 - 1.5) * 2.2;
  const pos = new V3(p.pos.x + F.x * 5 + R.x * off, 0, p.pos.z + F.z * 5 + R.z * off);
