  vbInit();
  VB.padT += dt;
  const oth = vbOther(team), remote = G.mp && NET.proxies ? [...NET.proxies.values()].find(px => px.alive && Math.hypot(px.pos.x - VB_PADS[oth].x, px.pos.z - VB_PADS[oth].z) < 2) : null;
