  if (remote) {
    const theirs = +(remote.net && remote.net.jt) || Infinity;
    const host = NET.joinT < theirs || (NET.joinT === theirs && String(NET.myPeer) < String(remote.peer));
    vbStart(team, remote, host ? 'host' : 'guest'); return;
  }
  VB.botT += dt;
  const left = Math.ceil(3 - VB.botT);
