$('bookbtn').addEventListener('click', e => { e.stopPropagation(); bookOpen(); });
$('book-x').addEventListener('click', bookClose);
$('bk-back').addEventListener('click', () => { SKB.ch = null; skGrid(); });
document.querySelectorAll('#book .bk-tabs button').forEach(b => b.addEventListener('click', () => bookTab(b.dataset.bk)));
$('book').addEventListener('click', e => { if (e.target === $('book')) bookClose(); });
addEventListener('keydown', e => {
  if (BIND_WAIT) return;
  const gKey = BINDS.guide || 'KeyK';
  if (CB.open) {
    const sel = d => CB.mode === 'skills' ? skSelect(clamp((SKB.idx || 0) + d, 0, SKB.list.length - 1)) : CB.mode === 'basic' ? cbSelect(CB.idx + d) : null;
    if (e.code === 'Escape') { if (CB.mode === 'skills') { SKB.ch = null; skGrid(); } else bookClose(); }
    else if (e.code === gKey) bookClose();
    else if (e.code === 'Backspace' && CB.mode === 'skills') { SKB.ch = null; skGrid(); }
    else if (e.code === 'ArrowDown' || e.code === 'ArrowRight') sel(1);
    else if (e.code === 'ArrowUp' || e.code === 'ArrowLeft') sel(-1);
    e.preventDefault(); e.stopImmediatePropagation(); return;
  }
  if (e.code === gKey && !e.repeat && G.state === 'play' && !G.paused && !G.over && !G.viewer && !G.panelOpen && e.target.tagName !== 'INPUT' && e.target.tagName !== 'TEXTAREA') { e.preventDefault(); e.stopImmediatePropagation(); bookOpen(); }
}, true);

const FPS = { el: null, n: 0, t: 0, on: false, ms: 0, worst: 0 };
try { FPS.on = localStorage.getItem('bsb_fps') === '1'; } catch (e) { FPS.on = false; }
addEventListener('keydown', e => { if (e.code === 'F2') { e.preventDefault(); FPS.on = !FPS.on; try { localStorage.setItem('bsb_fps', FPS.on ? '1' : '0'); } catch (x) { } if ($('opt-fps')) $('opt-fps').checked = FPS.on; if (FPS.el) FPS.el.style.display = FPS.on ? 'block' : 'none'; } });
function fpsTick(raw) {
  if (!FPS.on && !FPS.el) return;
  if (!FPS.el) { FPS.el = document.createElement('div'); FPS.el.style.cssText = 'position:fixed;top:6px;right:8px;z-index:99;pointer-events:none;font:700 12px/1.2 "Chakra Petch",monospace;color:#d7ff2f;text-shadow:0 1px 3px #000;background:#0008;padding:3px 7px;border-radius:5px;letter-spacing:.5px'; document.body.appendChild(FPS.el); }
  FPS.el.style.display = FPS.on ? 'block' : 'none'; FPS.n++; FPS.t += raw; FPS.ms = Math.max(FPS.ms, raw * 1000);
  if (FPS.t >= .4) {
    const fps = FPS.n / FPS.t;
    const frameMs = (1000 / Math.max(1, fps)).toFixed(1);
    FPS.el.style.color = fps >= 180 ? '#3ee07a' : fps >= 120 ? '#4fc3ff' : fps >= 50 ? '#d7ff2f' : fps >= 30 ? '#ffd23f' : '#ff4757';
    FPS.el.textContent = Math.round(fps) + ' FPS · ' + frameMs + ' ms · pico ' + Math.round(FPS.ms) + ' ms';
    FPS.n = 0; FPS.t = 0; FPS.ms = 0;
  }
}

// ====================================================================
// RESPLANDOR SOLAR SUAVE EN EL CIELO (sin líneas radiales sobre árboles)
// ====================================================================
function updateGodRays() {
  const gr = $('game-godrays');
  if (!gr) return;
  if (!GFX_CFG.godrays || G.state !== 'play' || (G.cine && G.cine.shot === 1) || (typeof WX !== 'undefined' && WX.cloud > 0.65) || sun.position.y <= 6) {
    gr.style.opacity = '0';
    return;
  }
  const camFwd = new THREE.Vector3(0, 0, -1).applyQuaternion(camera.quaternion);
  const sunPos = sun.position.clone().normalize();
  const dot = camFwd.dot(sunPos);
  if (dot > 0.05) {
    const sv = sunPos.clone().multiplyScalar(150).project(camera);
    const sx = clamp((sv.x * 0.5 + 0.5) * 100, 10, 90);
    const sy = clamp((-sv.y * 0.5 + 0.5) * 100, -25, 12);
    gr.style.setProperty('--sx', sx.toFixed(1) + '%');
    gr.style.setProperty('--sy', sy.toFixed(1) + '%');
    const alpha = clamp((dot - 0.05) / 0.85, 0, 1) * 0.42;
    gr.style.opacity = alpha.toFixed(2);
  } else {
    gr.style.opacity = '0';
  }
}

function loop(now){
  requestAnimationFrame(loop);
  if(IS_GUIDE&&GUIDE_OFF){last=Number.isFinite(now)?now:performance.now();return;}
  if (typeof GFX_LIMIT !== 'undefined' && GFX_LIMIT.minDt > 0) {
    const tNow = performance.now();
    const elapsed = tNow - GFX_LIMIT.lastFrame;
    if (elapsed < GFX_LIMIT.minDt * 0.88) return;
    GFX_LIMIT.lastFrame = tNow - (elapsed % GFX_LIMIT.minDt);
  }
  try{
  const rawDt=Number.isFinite(now)&&Number.isFinite(last)?Math.max(0,(now-last)/1000):0,rdt=Math.min(.05,rawDt);last=Number.isFinite(now)?now:performance.now();
  frameTask('contador',()=>{gfxWatch(rawDt);fpsTick(rawDt);});
  frameTask('caras',()=>updateFaceAnims(now/1000));
  for(const c of CLOUDS){c.position.x+=rdt*1.5;if(c.position.x>160)c.position.x=-160;}
  IMPACT.cd-=rdt;if(IMPACT.t>0)IMPACT.t-=rdt;
  if(typeof ME !== 'undefined' && ME.open){
    frameTask('culling',()=>cityCull());
    frameTask('ambiente',()=>updateAmbience(rdt));
    frameTask('clima',()=>updateCityWeather(0));
    frameTask('playa',()=>updateBeach(rdt));
    frameTask('mar',()=>updateSea(rdt));
    frameTask('editor3d',()=>meUpdateCam(rdt));
    updateFx(rdt);
    drawFrameSafely();
    return;
  }
  if(G.state==='title'){
    frameTask('culling',()=>cityCull());
    frameTask('ambiente',()=>updateAmbience(rdt));
    frameTask('musica',()=>updateMusic(rdt));frameTask('clima',()=>updateCityWeather(rdt));frameTask('playa',()=>updateBeach(rdt));frameTask('titulo',()=>titleUpdate(rdt));updateFx(rdt);return;
  }
  if(G.state==='menu'){
    frameTask('culling',()=>cityCull());
    frameTask('ambiente',()=>updateAmbience(rdt));
    frameTask('musica',()=>updateMusic(rdt));frameTask('clima',()=>updateCityWeather(0));frameTask('selector',()=>updateShow(rdt));updateFx(rdt);
    frameTask('lineas',()=>drawLines(rdt));return;
  }
  if(GS.on)frameTask('guia',()=>guideTick(rdt));
  if(G.cine&&!G.paused)frameTask('cinematica',()=>updateCine(rdt));
  else{
    let dt=rdt*(G.slowT>0?.3:1);if(G.slowT>0)G.slowT-=rdt;
    if((G.paused&&!G.mp)||G.over)dt=0;if(G.viewer)dt*=VW.play?VW.speed:0;
    if(G.hitstop>0){G.hitstop-=rdt*(G.viewer?(VW.play?VW.speed:0):1);dt=0;}
    if(dt>0)frameTask('simulacion',()=>step(dt),()=>pressed.clear());
    if(G.viewer)frameTask('visor',()=>vTick(dt));else if(G.paused)pressed.clear();
  }
  if(G.mp)frameTask('red',()=>guideNet(rdt));
  if(G.over&&G.winner&&G.winner.victory&&G.fighters.includes(G.winner))frameTask('victoria',()=>animate(G.winner,rdt));
  frameTask('camara:efectos',()=>updateCamFx(rdt));frameTask('camara',()=>{updateCamera(rdt);if(GS.on)guideCam(rdt);});frameTask('cielo',skyFollow);frameTask('rayos_sol',()=>updateGodRays());
  frameTask('clima',()=>updateCityWeather(G.paused&&!G.mp?0:rdt));frameTask('ambiente',()=>updateAmbience(rdt));frameTask('musica',()=>updateMusic(rawDt>.5?.05:rdt));
  frameTask('playa',()=>updateBeach(rdt));frameTask('mar',()=>updateSea(rdt));frameTask('cartel_mall',()=>updateMallBillboard(rdt));frameTask('bajoagua',()=>updateUnderwater(rdt));frameTask('culling',()=>cityCull());frameTask('voley',()=>updateVolley(rdt),()=>{if(VB.on)vbEnd('error');});
  if(G.hitstop>0&&G.chore&&G.chore.tg.model){const m=G.chore.tg.model.root;m.position.copy(G.chore.tg.pos);const pulse=Math.min(1,G.hitstop/.06);m.position.x+=Math.sin(now*.14)*.035*pulse;m.position.y+=Math.sin(now*.18)*.018*pulse;}
  frameTask('voces',()=>updateCharacterVoices());
  frameTask('interfaz',()=>updateHUD(rdt));frameTask('lineas',()=>drawLines(rdt));
  if(G.cine&&G.cine.shot===1)frameTask('paneles',()=>drawPanelBorders());
  }catch(error){reportFrameError('cuadro',error);}
  finally{drawFrameSafely();if(GS.on)guideBlit();}
}

